// The island's randomness surface ALONE — no digests, so this runs on
// every island lane (crypto-shims pins the hashing half and needs md5,
// which the Rust lane's ring does not carry). Everything below routes
// through globalThis.crypto.getRandomValues, which node:crypto's shim
// captures once at shim-factory time: without that global the whole
// surface throws on undefined. Shape-only by construction — the values
// are random, the lengths, types and untouched bytes are not.
import crypto, { randomBytes, randomFillSync, randomInt, randomUUID } from "node:crypto";

const uuidV4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

export function report() {
  const lines = [];
  const push = (label, v) => lines.push(label + " " + v);
  const throws = (fn) => {
    try {
      fn();
      return false;
    } catch {
      return true;
    }
  };

  const bytes = randomBytes(16);
  push("bytes:", bytes.length + "|" + Buffer.isBuffer(bytes) + "|" + randomBytes(0).length);
  // Past the 65536-byte chunk the shim splits on, so the chunking loop
  // itself is covered rather than just its first pass.
  push("bytes-big:", randomBytes(70000).length);

  push("uuid:", uuidV4.test(randomUUID()) + "|" + (randomUUID() !== randomUUID()));
  push("uuid-global:", uuidV4.test(globalThis.crypto.randomUUID()));

  const view = new Uint8Array(4);
  push("grv:", (crypto.getRandomValues(view) === view) + "|" + view.length);
  push("grv-global:", (globalThis.crypto.getRandomValues(view) === view));
  push("grv-empty:", crypto.getRandomValues(new Uint8Array(0)).length);
  const wide = new Uint32Array(3);
  crypto.getRandomValues(wide);
  push("grv-u32:", wide.length + "|" + wide.every((v) => Number.isInteger(v) && v >= 0));

  // A view over part of a larger buffer must be filled at its OWN byte
  // offset — the bytes outside it stay zero.
  const framed = new Uint8Array(8);
  crypto.getRandomValues(framed.subarray(2, 6));
  push("grv-offset:", framed[0] + "," + framed[1] + "," + framed[6] + "," + framed[7]);

  // Both refusals throw everywhere, but Node codes them ERR_INVALID_ARG_TYPE
  // where the island raises the WebCrypto DOMException names, so only the
  // throw itself is differential.
  push("grv-bad:", throws(() => crypto.getRandomValues([1, 2, 3])));
  push("grv-quota:", throws(() => crypto.getRandomValues(new Uint8Array(65537))));

  const filled = Buffer.alloc(8);
  push("fill:", (randomFillSync(filled, 2, 4) === filled) + "|" + filled.readUInt16LE(0) + "|" + filled.readUInt16LE(6));

  let inRange = true;
  for (let i = 0; i < 100; i += 1) {
    const v = randomInt(3, 6);
    if (v < 3 || v >= 6 || !Number.isInteger(v)) inRange = false;
  }
  push("int:", inRange);

  return lines.join("\n");
}
